-- Refresh Supabase's column cache so new columns are visible to the site immediately.
notify pgrst, 'reload schema';


-- =====================================================================
-- PART 2: SECURITY LOCKDOWN
-- =====================================================================

-- =====================================================================
-- SECURITY LOCKDOWN — run ONLY after the new code is deployed and the
-- admin panel has been verified working (see SECURITY-DEPLOY.md).
--
-- Before this: the public anon key (visible to anyone in your site's
-- JavaScript) could write to your database directly, bypassing your
-- login entirely.
-- After this:  anon can only READ the content that's meant to be public.
-- Every write goes through your API routes, which check your login
-- session and use the server-only service-role key (which bypasses RLS).
--
-- Safe to re-run. Tables that don't exist yet are skipped.
-- =====================================================================

-- 0. Columns the public-read policies depend on --------------------------
do $$
begin
  if to_regclass('public.projects') is not null then
    execute 'alter table public.projects add column if not exists published boolean not null default true';
  end if;
  if to_regclass('public.designs') is not null then
    execute 'alter table public.designs add column if not exists published boolean not null default true';
  end if;
end $$;

-- 1. Drop EVERY existing policy on these tables ---------------------------
-- (their names/contents are unknown — some may be "allow all" policies
-- that are exactly what we're removing)
do $$
declare r record;
begin
  for r in
    select schemaname, tablename, policyname from pg_policies
    where schemaname = 'public' and tablename in (
      'articles','projects','designs','services','service_packages','testimonials',
      'products','journey_entries','courses','course_lessons','certifications','experiences','education',
      'projects_resume','roadmap_items','client_logos','site_settings',
      'messages','newsletter_subscribers','orders','rate_limit_log',
      'login_attempts','activity_log','security_audit_log','admin_totp_used','private_settings','discount_codes','invoices','site_searches','proposals','time_entries','client_projects','feedback_boards','feedback_comments','post_comments','newsletter_campaigns','recruiter_packs','recruiter_events','link_clicks','error_reports','content_items','product_reviews'
    )
  loop
    execute format('drop policy %I on %I.%I', r.policyname, r.schemaname, r.tablename);
  end loop;
end $$;

-- 2. Row Level Security ON for every table --------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'articles','projects','designs','services','service_packages','testimonials',
    'products','journey_entries','courses','course_lessons','certifications','experiences','education',
    'projects_resume','roadmap_items','client_logos','site_settings',
    'messages','newsletter_subscribers','orders','rate_limit_log',
    'login_attempts','activity_log','security_audit_log','admin_totp_used','private_settings','discount_codes','invoices','site_searches','proposals','time_entries','client_projects','feedback_boards','feedback_comments','post_comments','newsletter_campaigns','recruiter_packs','recruiter_events','link_clicks','error_reports','content_items','product_reviews'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('alter table public.%I enable row level security', t);
    end if;
  end loop;
end $$;

-- 3. No anonymous / logged-in-via-Supabase writes anywhere ----------------
-- (belt and braces: RLS already denies these without a policy, but
-- revoking the privilege means a future mistaken policy can't re-open it)
do $$
declare t text;
begin
  foreach t in array array[
    'articles','projects','designs','services','service_packages','testimonials',
    'products','journey_entries','courses','course_lessons','certifications','experiences','education',
    'projects_resume','roadmap_items','client_logos','site_settings'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('revoke insert, update, delete, truncate, references, trigger on public.%I from anon, authenticated', t);
      if t not in ('projects','articles','designs') then
        execute format('grant select on public.%I to anon, authenticated', t);
      else
        execute format('revoke select on public.%I from anon, authenticated', t);
        execute format('revoke select (preview_token) on public.%I from anon, authenticated', t);
        execute format('grant select (%s) on public.%I to anon, authenticated',
          (select string_agg(quote_ident(column_name), ',') from information_schema.columns
            where table_schema = 'public' and table_name = t and column_name <> 'preview_token'), t);
      end if;
    end if;
  end loop;

  -- Private tables: no access at all for anon/authenticated. Only the
  -- service-role key (server-side API routes) can touch these.
  foreach t in array array[
    'messages','newsletter_subscribers','orders','rate_limit_log',
    'login_attempts','activity_log','security_audit_log','admin_totp_used','private_settings','discount_codes','invoices','site_searches','proposals','time_entries','client_projects','feedback_boards','feedback_comments','post_comments','newsletter_campaigns','recruiter_packs','recruiter_events','link_clicks','error_reports','content_items','product_reviews'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('revoke all on public.%I from anon, authenticated', t);
    end if;
  end loop;
end $$;

-- 4. Public READ policies — only what the public site actually shows ------
do $$
declare v record;
begin
  for v in select * from (values
    ('articles',         'published = true and (publish_at is null or publish_at <= now())'),  -- scheduled posts stay hidden until their time
    ('projects',         'published = true'),
    ('designs',          'published = true'),
    ('services',         'active = true'),
    ('service_packages', 'exists (select 1 from public.services s where s.id = service_packages.service_id)'),
    ('testimonials',     'active = true'),
    ('products',         'active = true'),
    ('journey_entries',  'true'),
    ('courses',          'published = true'),
    ('course_lessons',   'exists (select 1 from public.courses c where c.id = course_lessons.course_id and c.published)'),
    ('certifications',   'true'),
    ('experiences',      'true'),
    ('education',        'true'),
    ('projects_resume',  'true'),
    ('roadmap_items',    'true'),
    ('client_logos',     'true'),
    ('site_settings',    'true')
  ) as x(tbl, cond)
  loop
    if to_regclass('public.' || v.tbl) is not null then
      execute format(
        'create policy "public read" on public.%I for select to anon, authenticated using (%s)',
        v.tbl, v.cond
      );
    end if;
  end loop;
end $$;

-- 5. Hide the paid download link from the public ---------------------------
-- products is publicly readable (it's your shop catalog), but
-- digital_file_url is the actual paid file. Column-level privileges let
-- everyone read the catalog columns while that one column stays private;
-- buyers get it only through /api/orders/download after a verified payment.
do $$
declare cols text;
begin
  if to_regclass('public.products') is not null then
    select string_agg(quote_ident(column_name), ', ') into cols
    from information_schema.columns
    where table_schema = 'public' and table_name = 'products'
      and column_name <> 'digital_file_url'
      and column_name <> 'wallpaper_files';   -- paid wallpaper files, same reason
    execute 'revoke select on public.products from anon, authenticated';
    execute format('grant select (%s) on public.products to anon, authenticated', cols);
  end if;
end $$;
-- NOTE: if you later add a column to products that the public shop should
-- show, re-run this file (or: grant select (new_column) on products to anon).

-- 6. Storage: no anonymous uploads / overwrites / deletes -------------------
-- Admin uploads now go through short-lived signed URLs minted by
-- /api/admin/upload-url (login + file-type + size checked there). Public
-- viewing of already-uploaded images is unaffected (public buckets serve
-- files without policies).
do $$
declare r record;
begin
  for r in
    select policyname from pg_policies
    where schemaname = 'storage' and tablename = 'objects'
      and cmd in ('INSERT','UPDATE','DELETE','ALL')
  loop
    execute format('drop policy %I on storage.objects', r.policyname);
  end loop;
end $$;

-- Hard cap enforced by Storage itself, independent of the app (250 MB).
update storage.buckets set file_size_limit = 262144000
where id in ('blog-images', 'resume-images');

-- OPTIONAL hardening (uncomment if you want it): make any table you create
-- in future private-by-default, so a new table is never accidentally public
-- until you grant it on purpose.
-- alter default privileges in schema public revoke all on tables from anon, authenticated;

-- Apply to an existing site before deploying the updated application.
begin;

-- Previously published items may have exposed their preview URLs. Rotate once.
create or replace function public.rotate_preview_on_unpublish() returns trigger
language plpgsql as $$
begin
  if old.published and not new.published then new.preview_token := gen_random_uuid()::text; end if;
  return new;
end $$;

do $$
declare t text; cols text;
begin
  foreach t in array array['projects','designs','articles'] loop
    select string_agg(quote_ident(column_name), ',') into cols from information_schema.columns
      where table_schema = 'public' and table_name = t and column_name <> 'preview_token';
    execute format('revoke select on public.%I from public, anon, authenticated', t);
    execute format('revoke select (preview_token) on public.%I from public, anon, authenticated', t);
    execute format('grant select (%s) on public.%I to anon, authenticated', cols, t);
    if not exists (select from pg_trigger where tgrelid = format('public.%I',t)::regclass and tgname = 'rotate_preview') then
      execute format('update public.%I set preview_token = gen_random_uuid()::text', t);
      execute format('create trigger rotate_preview before update of published on public.%I for each row execute function public.rotate_preview_on_unpublish()', t);
    end if;
  end loop;
end $$;

alter table public.orders add column if not exists stock_reserved boolean not null default false;

-- Product availability, discount use, inventory reservation and the order commit together.
create or replace function public.place_shop_order(payload jsonb) returns uuid
language plpgsql set search_path = public as $$
declare
  o orders := jsonb_populate_record(null::orders, payload);
  p products;
  d record;
  amount numeric := 0;
  reserved boolean;
begin
  select * into p from products where id = o.product_id and active for update;
  if not found then raise exception 'Product unavailable' using errcode = 'P0001'; end if;
  reserved := p.type = 'physical' and p.stock_quantity is not null;
  if reserved then
    if p.stock_quantity <= 0 then raise exception 'Out of stock'; end if;
    update products set stock_quantity = stock_quantity - 1 where id = p.id;
  end if;
  if o.discount_code is not null then
    select * into d from redeem_discount(o.discount_code);
    if not found then raise exception 'Discount is no longer available'; end if;
    amount := round(least(p.price, case when d.kind = 'percent' then p.price*d.value/100 else d.value end),2);
  end if;
  if o.product_price is distinct from p.price - amount then raise exception 'Price changed. Refresh checkout.'; end if;
  insert into orders (id, order_number, product_id, product_name, product_price, discount_code, discount_amount,
    amount_local, currency_local, customer_name, customer_email, payment_method, customer_transaction_id, status,
    payment_proof, payment_provider, stock_reserved)
  values (coalesce(o.id, gen_random_uuid()), o.order_number, p.id, p.name, p.price - amount, o.discount_code, amount,
    o.amount_local, o.currency_local, o.customer_name, o.customer_email, o.payment_method, o.customer_transaction_id,
    o.status, o.payment_proof, o.payment_provider, reserved) returning id into o.id;
  return o.id;
end $$;

create or replace function public.release_order_stock() returns trigger language plpgsql set search_path = public as $$
begin
  if old.stock_reserved and new.status in ('rejected','refunded') then
    update products set stock_quantity = stock_quantity + 1 where id = old.product_id;
    new.stock_reserved := false;
  end if;
  return new;
end $$;
drop trigger if exists release_order_stock on public.orders;
create trigger release_order_stock before update of status on public.orders
  for each row execute function public.release_order_stock();

create or replace function public.claim_shop_order(order_id uuid) returns jsonb
language plpgsql set search_path = public as $$
declare o orders; p products;
begin
  select * into o from orders where id = order_id for update;
  if not found then return jsonb_build_object('status',404,'error','Order not found'); end if;
  if o.status = 'paid' then return jsonb_build_object('alreadyPaid',true,'order',to_jsonb(o)); end if;
  if o.status not in ('pending_verification','awaiting_card') then
    return jsonb_build_object('status',409,'error','Order is no longer pending');
  end if;
  -- Older pending orders predate stock reservations.
  if not o.stock_reserved then
    select * into p from products where id = o.product_id for update;
    if p.type = 'physical' and p.stock_quantity is not null then
      if p.stock_quantity <= 0 then return jsonb_build_object('status',409,'error','Out of stock'); end if;
      update products set stock_quantity = stock_quantity - 1 where id = p.id;
      o.stock_reserved := true;
    end if;
  end if;
  update orders set status = 'paid', verified_at = now(), download_token = gen_random_uuid()::text,
    stock_reserved = o.stock_reserved where id = order_id returning * into o;
  return jsonb_build_object('alreadyPaid',false,'order',to_jsonb(o));
end $$;

create table if not exists public.billing_numbers (prefix text primary key, last_number bigint not null);
alter table public.billing_numbers enable row level security;
revoke all on public.billing_numbers from public, anon, authenticated;
grant select, insert, update on public.billing_numbers to service_role;

create or replace function public.next_billing_number(series text) returns text
language plpgsql set search_path = public as $$
declare prefix_text text := series || '-' || extract(year from current_date)::int || '-';
  n bigint; suffix text;
begin
  if series not in ('INV','PRO') then raise exception 'Unknown numbering series'; end if;
  execute format('select coalesce(max(substring(number from %L)::bigint),0) from %I',
    '^' || prefix_text || '([0-9]+)$', case series when 'INV' then 'invoices' else 'proposals' end) into n;
  insert into billing_numbers as b (prefix,last_number) values (prefix_text,n+1)
    on conflict (prefix) do update set last_number = greatest(b.last_number+1, excluded.last_number)
    returning last_number::text into suffix;
  return prefix_text || lpad(suffix,greatest(3,length(suffix)),'0');
end $$;

create or replace function public.accept_proposal(proposal_token text, signer text, fingerprint text) returns jsonb
language plpgsql set search_path = public as $$
declare p proposals; inv invoices;
begin
  select * into p from proposals where public_token = proposal_token and status = 'sent' for update;
  if not found or p.valid_until < current_date then return null; end if;
  insert into invoices (number, client_name, client_email, currency, items, discount, tax_percent, notes, status, due_date, sent_at)
    values(next_billing_number('INV'),p.client_name,p.client_email,p.currency,p.items,p.discount,p.tax_percent,
      'For proposal ' || p.number || ': ' || p.title,'sent',current_date + 14,now()) returning * into inv;
  update proposals set status = 'accepted', accepted_at = now(), signed_name = signer, signed_ip_hash = fingerprint,
    invoice_id = inv.id where id = p.id;
  update messages set stage = 'won' where id = p.lead_id;
  return jsonb_build_object('number',inv.number,'public_token',inv.public_token);
end $$;

alter table public.invoices add column if not exists repeat_anchor_day integer;
create or replace function public.repeat_invoice(source_id uuid, scheduled date) returns jsonb
language plpgsql set search_path = public as $$
declare src invoices; copy invoices; month_start date; anchor integer;
begin
  select * into src from invoices where id = source_id and repeat_monthly and repeat_next = scheduled
    and scheduled <= current_date for update;
  if not found then return null; end if;
  anchor := coalesce(src.repeat_anchor_day, extract(day from scheduled)::int);
  month_start := (date_trunc('month', scheduled) + interval '1 month')::date;
  insert into invoices (number,client_name,client_email,client_address,currency,items,discount,tax_percent,notes,status,
    issue_date,due_date,sent_at,repeated_from)
    values(next_billing_number('INV'),src.client_name,src.client_email,src.client_address,src.currency,src.items,
      src.discount,src.tax_percent,src.notes,'sent',current_date,current_date + 14,now(),src.id) returning * into copy;
  update invoices set repeat_anchor_day = anchor, repeat_next = least(month_start + (anchor - 1),
    (month_start + interval '1 month - 1 day')::date) where id = src.id;
  return to_jsonb(copy);
end $$;

revoke all on function public.place_shop_order(jsonb), public.claim_shop_order(uuid), public.next_billing_number(text),
  public.accept_proposal(text,text,text), public.repeat_invoice(uuid,date) from public,anon,authenticated;
grant execute on function public.place_shop_order(jsonb), public.claim_shop_order(uuid), public.next_billing_number(text),
  public.accept_proposal(text,text,text), public.repeat_invoice(uuid,date) to service_role;
commit;

-- Apply once before deploying work-linked testimonials. Existing reviews stay general.
begin;
alter table public.testimonials
  add column if not exists project_id uuid references public.projects(id) on delete set null,
  add column if not exists design_id uuid references public.designs(id) on delete set null,
  add column if not exists client_id uuid references public.client_logos(id) on delete set null;
do $$
begin
  if not exists (select from pg_constraint where conrelid='public.testimonials'::regclass and conname='testimonials_one_work') then
    alter table public.testimonials add constraint testimonials_one_work check (num_nonnulls(project_id, design_id, client_id) <= 1);
  end if;
end $$;

-- Reuse the portfolio's UES client, keeping its ID, existing slug, artwork and custom copy.
do $$
declare
  client_uuid uuid;
  study text := $copy$## UMT Business Fest 2026
For UMT Business Fest 2026, I designed the event graphics for the UMT Entrepreneurial Society (UES). My work covered two places people would encounter the fest: on Instagram before and around the event, and in print at the venue.

## Designing for the venue
At the venue, I designed ID cards, flexes, banners and standees. Those formats pose different reading problems: an ID card is read up close, while a banner or standee has to communicate from several steps away. That difference in scale is a useful way to look at the print work in this collection.

## From grid to Story
For Instagram, I designed social posts, grid posts and Stories. A grid can be viewed as a whole or one square at a time; a Story has the width of a phone screen and only a moment to catch the eye. Together with the print pieces, these designs show how the same event takes shape across a venue and a feed.$copy$;
begin
  select id into client_uuid from public.client_logos
    where slug='ues' or lower(trim(name)) in ('ues','umt entrepreneurial society')
    order by (slug='ues') desc nulls last, created_at limit 1;
  if client_uuid is null then
    insert into public.client_logos(name,slug,image_url,dark_image_url,role,summary,show_on_design,order_index)
    values ('UMT Entrepreneurial Society','ues','/logos/umt-entrepreneurial-society-dark.png','/logos/umt-entrepreneurial-society-light.png','Graphic designer · UMT Business Fest 2026',study,true,2);
  else
    update public.client_logos set slug=coalesce(nullif(slug,''),'ues'),
      role=coalesce(nullif(role,''),'Graphic designer · UMT Business Fest 2026'),
      summary=case when nullif(trim(summary),'') is null then study
        when position(study in summary)>0 then summary
        else summary || E'\n\n' || study end,
      show_on_design=true where id=client_uuid;
  end if;
end $$;
commit;

begin;
create table if not exists public.design_campaigns (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.client_logos(id) on delete cascade,
  title text not null check (length(trim(title)) between 1 and 160),
  summary text not null default '',
  role text,
  share_image_url text,
  published boolean not null default false,
  created_at timestamptz not null default now(),
  unique (id, client_id)
);
alter table public.design_campaigns enable row level security;
revoke all on public.design_campaigns from anon, authenticated;
grant select on public.design_campaigns to anon, authenticated;
grant all on public.design_campaigns to service_role;
drop policy if exists campaign_public_read on public.design_campaigns;
create policy campaign_public_read on public.design_campaigns for select to anon, authenticated
  using (published and exists (select 1 from public.client_logos c where c.id=client_id and c.show_on_design));

alter table public.designs add column if not exists campaign_id uuid references public.design_campaigns(id) on delete set null;
alter table public.designs add column if not exists needs text[] not null default '{}';
alter table public.client_logos add column if not exists share_image_url text;
grant select (campaign_id, needs) on public.designs to anon, authenticated;
create index if not exists designs_campaign_idx on public.designs(campaign_id);
create index if not exists design_campaigns_client_idx on public.design_campaigns(client_id);

-- Enforce the association on every write, including the existing generic admin endpoint.
create or replace function public.check_design_campaign() returns trigger
language plpgsql set search_path=public as $$
begin
  if TG_OP='UPDATE' and new.client_id is distinct from old.client_id
     and new.campaign_id is not distinct from old.campaign_id then
    new.campaign_id := null;
  end if;
  if new.campaign_id is not null and new.client_id is null then
    raise exception 'Choose a client for this campaign';
  end if;
  return new;
end $$;
drop trigger if exists design_campaign_guard on public.designs;
create trigger design_campaign_guard before insert or update on public.designs
  for each row execute function public.check_design_campaign();
do $$ begin
  if not exists(select 1 from pg_constraint where conname='design_campaign_client_match' and conrelid='public.designs'::regclass) then
    alter table public.designs add constraint design_campaign_client_match
      foreign key(campaign_id,client_id) references public.design_campaigns(id,client_id);
  end if;
end $$;

-- Create the requested campaign as a draft. The owner chooses which designs belong to it.
insert into public.design_campaigns(client_id,title,role,summary)
select id, 'UMT Business Fest 2026', 'Graphic designer',
'For UMT Business Fest 2026, I designed event graphics for the UMT Entrepreneurial Society.

The print work included ID cards, flexes, banners and standees. These pieces brought the event into the venue, from identification worn by participants to larger displays.

The digital work included social media posts, Instagram grid posts and Stories. This collection brings the print and digital pieces together as one event portfolio.'
from public.client_logos c
where (c.slug='ues' or lower(trim(c.name)) in ('ues','umt entrepreneurial society'))
and not exists(select 1 from public.design_campaigns d where d.client_id=c.id and d.title='UMT Business Fest 2026');
notify pgrst, 'reload schema';
commit;

-- Run after 2026-11-design-campaigns.sql.
begin;
alter table public.testimonials
  add column if not exists project_id uuid references public.projects(id) on delete set null,
  add column if not exists design_id uuid references public.designs(id) on delete set null,
  add column if not exists client_id uuid references public.client_logos(id) on delete set null;
alter table public.testimonials add column if not exists campaign_id uuid
  references public.design_campaigns(id) on delete set null;
alter table public.testimonials drop constraint if exists testimonials_one_work;
alter table public.testimonials add constraint testimonials_one_work
  check (num_nonnulls(project_id,design_id,client_id,campaign_id) <= 1);
create index if not exists testimonials_client_active_idx on public.testimonials(client_id) where active;
create index if not exists testimonials_design_active_idx on public.testimonials(design_id) where active;
create index if not exists testimonials_campaign_active_idx on public.testimonials(campaign_id) where active;

-- Update the earlier generated copy. Keep independently edited case-study text.
update public.client_logos
set summary = $study$## Design work for UMT Entrepreneurial Society
My work for the UMT Entrepreneurial Society (UES) includes the event graphics for UMT Business Fest 2026. The project brought together printed material for the venue and digital designs for Instagram.

## One event across many formats
I designed ID cards, flexes, banners and standees alongside social media posts, Instagram grid posts and Stories. The collection includes registration announcements and material for Students Expo and CEO Talks.

## Reading the work
An ID card has to work at close range. A standee or banner needs to communicate from farther away. A grid post can be encountered as one image or as part of a larger composition, while a Story is viewed vertically on a phone. These differences in scale and placement provide the context for the designs below.

## Explore the collection
The Business Fest campaign brings the event pieces together in one case study. Open an individual design to view its complete artwork, or save examples to a project brief if you are planning a similar event.$study$
where (lower(trim(name)) in ('ues','umt entrepreneurial society') or slug='ues')
  and (nullif(trim(summary),'') is null or summary like '## UMT Business Fest 2026%');

update public.design_campaigns
set summary = $study$## UMT Business Fest 2026
I created print and digital graphics for UMT Business Fest 2026 with the UMT Entrepreneurial Society. The scope covered the materials people would encounter while discovering the event online and attending it on campus.

## The design challenge
The collection had to work across very different sizes and placements. Registration information on a phone, an ID card worn at the venue, and a large event display each ask the viewer to read in a different way. This case study brings those formats together so they can be viewed in context.

## Print and venue graphics
My deliverables included ID cards, flexes, banners and standees. The posters shown in this portfolio combine event information, typography, architectural imagery and registration details. They include material for Students Expo and CEO Talks, alongside broader event and registration announcements.

## Instagram and social media
I also designed social media posts, Instagram grid posts and Stories. The grid work uses connected compositions across several posts, while other pieces present a single announcement. The gallery preserves the full artwork so the complete layout can be explored.

## Project scope
This collection documents my graphic design contribution across the event's print and social formats. The artwork below shows the deliverables, and approved testimonials record the experiences of the people I worked with.$study$
where title='UMT Business Fest 2026'
  and client_id in (select id from public.client_logos where lower(trim(name)) in ('ues','umt entrepreneurial society') or slug='ues')
  and (nullif(trim(summary),'') is null or summary like 'For UMT Business Fest 2026, I designed event graphics for the UMT Entrepreneurial Society.%');
notify pgrst, 'reload schema';
commit;
